import { Deadline } from "uniswap/src/features/transactions/swap/form/header/SwapFormSettings/settingsConfigurations/Deadline/Deadline";
import { Slippage } from "uniswap/src/features/transactions/swap/form/header/SwapFormSettings/settingsConfigurations/Slippage/Slippage";
import { usePrevious } from "utilities/src/react/hooks";
const WIDTH = {
  positionCard: 600,
  sidebar: 360
};
function CreatePositionInner() {
  const {
    positionState: { protocolVersion },
    derivedPositionInfo: { creatingPoolOrPair },
    step,
    setStep
  } = useCreatePositionContext();
  const v2Selected = protocolVersion === ProtocolVersion.V2;
  const { error, refetch } = useCreateTxContext();
  const handleContinue = useCallback(() => {
    if (v2Selected) {
      if (step === PositionFlowStep.SELECT_TOKENS_AND_FEE_TIER && creatingPoolOrPair) {
        setStep(PositionFlowStep.PRICE_RANGE);
      } else {
        setStep(PositionFlowStep.DEPOSIT);
      }
    } else {
      setStep((prevStep) => prevStep + 1);
    }
  }, [creatingPoolOrPair, setStep, step, v2Selected]);
  if (step === PositionFlowStep.SELECT_TOKENS_AND_FEE_TIER) {
    return <Trace logImpression section={SectionName.CreatePositionSelectTokensStep}>
        <SelectTokensStep onContinue={handleContinue} />
      </Trace>;
  }
  if (step === PositionFlowStep.PRICE_RANGE) {
    return <Trace logImpression section={SectionName.CreatePositionPriceRangeStep}>
        <EditSelectTokensStep />
        <Container>
          <SelectPriceRangeStep />
          <DepositStep />
          <ErrorCallout errorMessage={error} onPress={refetch} />
        </Container>
      </Trace>;
  }
  return <Trace logImpression section={SectionName.CreatePositionDepositStep}>
      <EditSelectTokensStep />
      <Container>
        <DepositStep />
      </Container>
      <ErrorCallout errorMessage={error} onPress={refetch} />
    </Trace>;
}
const Sidebar = () => {
  const { t } = useTranslation();
  const {
    positionState: { protocolVersion },
    derivedPositionInfo: { creatingPoolOrPair },
    step,
    setStep
  } = useCreatePositionContext();
  const PoolProgressSteps = useMemo(() => {
    const createStep = (label, stepEnum) => ({
      label,
      active: step === stepEnum,
      // This relies on the ordering of PositionFlowStep enum values matching the actual order in the form.
      onPress: stepEnum < step ? () => setStep(stepEnum) : void 0
    });
    if (protocolVersion === ProtocolVersion.V2) {
      if (creatingPoolOrPair) {
        return [
          createStep(t(`position.step.select`), PositionFlowStep.SELECT_TOKENS_AND_FEE_TIER),
          createStep(t("position.step.price"), PositionFlowStep.PRICE_RANGE)
        ];
      }
      return [
        createStep(t("position.step.select"), PositionFlowStep.SELECT_TOKENS_AND_FEE_TIER),
        createStep(t("position.step.deposit"), PositionFlowStep.DEPOSIT)
      ];
    }
    return [
      createStep(t("position.step.select"), PositionFlowStep.SELECT_TOKENS_AND_FEE_TIER),
      createStep(t("position.step.range"), PositionFlowStep.PRICE_RANGE)
    ];
  }, [creatingPoolOrPair, protocolVersion, setStep, step, t]);
  return <Flex
    width={WIDTH.sidebar}
    alignSelf="flex-start"
    $platform-web={{ position: "sticky", top: INTERFACE_NAV_HEIGHT + 25 }}
  >
      <PoolProgressIndicator steps={PoolProgressSteps} />
    </Flex>;
};
const ResetButton = ({ onClickReset, isDisabled }) => {
  const { t } = useTranslation();
  return <Button size="small" emphasis="tertiary" onPress={onClickReset} isDisabled={isDisabled} icon={<RotateLeft />}>
      {t("common.button.reset")}
    </Button>;
};
const ToolbarContainer = styled(Flex, {
  row: true,
  centered: true,
  gap: "$gap12",
  $md: {
    "$platform-web": {
      display: "grid",
      gridTemplateColumns: "1fr 1fr auto",
      gridColumnGap: "8px"
    }
  }
});
const Toolbar = ({ defaultInitialToken }) => {
  const navigate = useNavigate();
  const { t } = useTranslation();
  const { positionState, setPositionState, setStep, reset: resetCreatePositionState } = useCreatePositionContext();
  const { protocolVersion } = positionState;
  const { setPriceRangeState } = usePriceRangeContext();
  const { customSlippageTolerance } = useTransactionSettingsContext();
  const [versionDropdownOpen, setVersionDropdownOpen] = useState(false);
  const [showResetModal, setShowResetModal] = useState(false);
  const { priceRangeState, reset: resetPriceRangeState } = usePriceRangeContext();
  const { depositState, reset: resetDepositState } = useDepositContext();
  const { reset: resetMultichainState } = useMultichainContext();
  const { isTestnetModeEnabled } = useEnabledChains();
  const prevIsTestnetModeEnabled = usePrevious(isTestnetModeEnabled) ?? false;
  const isFormUnchanged = useMemo(() => {
    return positionState.currencyInputs.TOKEN0 === defaultInitialToken && !positionState.currencyInputs.TOKEN1 && positionState.fee === DEFAULT_POSITION_STATE.fee && positionState.poolType.stable === DEFAULT_POSITION_STATE.poolType.stable && positionState.hook === DEFAULT_POSITION_STATE.hook && priceRangeState.initialPrice === DEFAULT_PRICE_RANGE_STATE.initialPrice && depositState === DEFAULT_DEPOSIT_STATE;
  }, [
    positionState.currencyInputs,
    positionState.fee,
    positionState.poolType,
    positionState.hook,
    priceRangeState,
    depositState,
    defaultInitialToken
  ]);
  const handleReset = useCallback(() => {
    resetCreatePositionState();
    resetPriceRangeState();
    resetMultichainState();
    resetDepositState();
  }, [resetDepositState, resetCreatePositionState, resetMultichainState, resetPriceRangeState]);
  useEffect(() => {
    if (isTestnetModeEnabled !== prevIsTestnetModeEnabled) {
      handleReset();
    }
  }, [handleReset, isTestnetModeEnabled, prevIsTestnetModeEnabled]);
  const handleVersionChange = useCallback(
    (version) => {
      const versionUrl = getProtocolVersionLabel(version);
      if (versionUrl) {
        navigate(`/positions/create/${versionUrl}`);
      }
      setPositionState((prevState) => ({
        ...DEFAULT_POSITION_STATE,
        currencyInputs: prevState.currencyInputs,
        protocolVersion: version
      }));
      setPriceRangeState(DEFAULT_PRICE_RANGE_STATE);
      setStep(PositionFlowStep.SELECT_TOKENS_AND_FEE_TIER);
      setVersionDropdownOpen(false);
    },
    [setPositionState, setPriceRangeState, setStep, navigate, setVersionDropdownOpen]
  );
  const versionOptions = useMemo(
    () => [ProtocolVersion.V3, ProtocolVersion.V2].filter((version) => version != protocolVersion).map((version) => <TouchableArea key={`version-${version}`} onPress={() => handleVersionChange(version)}>
            <Flex p="$spacing8" borderRadius="$rounded8" hoverStyle={{ backgroundColor: "$surface2" }}>
              <Text variant="body2">{version == 2 ? "Concentrated" : "Basic"}</Text>
            </Flex>
          </TouchableArea>),
    [handleVersionChange, protocolVersion, t]
  );
  return <Flex>
      <ResetCreatePositionFormModal
    isOpen={showResetModal}
    onClose={() => setShowResetModal(false)}
    onHandleReset={handleReset}
  />

      <ToolbarContainer>
        <ResetButton onClickReset={() => setShowResetModal(true)} isDisabled={isFormUnchanged} />

        <Popover open={versionDropdownOpen} onOpenChange={setVersionDropdownOpen}>
          <Popover.Trigger>
            <TouchableArea
    borderRadius="$rounded12"
    borderWidth="$spacing1"
    borderColor="$surface3"
    height="38px"
    px="$gap8"
    alignItems="center"
    justifyContent="center"
    flexDirection="row"
    gap="$gap4"
    width={140}
    hoverStyle={{ backgroundColor: "$surface2" }}
  >
              <Text variant="body2">{protocolVersion == 2 ? "Concentrated" : "Basic"}</Text>

              <ChevronDown size={16} />
            </TouchableArea>
          </Popover.Trigger>
          <Popover.Content
    animation={[
      "quick",
      {
        opacity: {
          overshootClamping: true
        }
      }
    ]}
    borderColor="$surface3"
    borderRadius="$rounded16"
    borderWidth="$spacing1"
    disableRemoveScroll={false}
    enterStyle={{ y: -10, opacity: 0 }}
    exitStyle={{ y: -10, opacity: 0 }}
    mt={"$spacing8"}
    p={"$none"}
  >
            <Flex p="$spacing4" minWidth={140}>
              {versionOptions}
            </Flex>
          </Popover.Content>
        </Popover>

        <Flex
    borderRadius="$rounded12"
    borderWidth={!customSlippageTolerance ? "$spacing1" : "$none"}
    borderColor="$surface3"
    height="38px"
    px={!customSlippageTolerance ? "$gap8" : "$gap4"}
    alignItems="center"
    pt="$spacing2"
  >
          <SwapFormSettings
    position="relative"
    adjustRightAlignment={false}
    adjustTopAlignment={false}
    settings={[Slippage, Deadline]}
    iconColor="$neutral1"
    iconSize="$icon.16"
  />
        </Flex>
      </ToolbarContainer>
    </Flex>;
};
export default function CreatePosition() {
  const media = useMedia();
  const { t } = useTranslation();
  const { protocolVersion } = useParams();
  const paramsProtocolVersion = parseProtocolVersion(protocolVersion);
  const autoSlippageTolerance = useLPSlippageValue(paramsProtocolVersion);
  const initialInputs = useInitialPoolInputs();
  const initialProtocolVersion = paramsProtocolVersion ?? ProtocolVersion.V4;
  const initialState = useMemo(() => {
    const baseState = {
      currencyInputs: {
        [PositionField.TOKEN0]: initialInputs[PositionField.TOKEN0],
        [PositionField.TOKEN1]: initialInputs[PositionField.TOKEN1]
      },
      protocolVersion: initialProtocolVersion
    };
    if (initialInputs.urlParams?.tickSpacing && initialProtocolVersion === ProtocolVersion.V3) {
      const tickSpacing = initialInputs.urlParams.tickSpacing;
      const feeAmount = tickSpacing === 1 ? 100 : tickSpacing === 50 ? 500 : tickSpacing === 100 ? 500 : tickSpacing === 200 ? 3e3 : tickSpacing === 2e3 ? 1e4 : 3e3;
      return {
        ...baseState,
        fee: { feeAmount, tickSpacing }
      };
    }
    if (initialInputs.urlParams && initialProtocolVersion === ProtocolVersion.V2) {
      return {
        ...baseState,
        poolType: {
          stable: initialInputs.urlParams.stable,
          label: initialInputs.urlParams.stable ? "stable" : "volatile"
        }
      };
    }
    return baseState;
  }, [initialInputs, initialProtocolVersion]);
  return <Trace logImpression page={InterfacePageNameLocal.CreatePosition}>
      <MultichainContextProvider initialChainId={initialInputs[PositionField.TOKEN0].chainId}>
        <TransactionSettingsContextProvider
    autoSlippageTolerance={autoSlippageTolerance}
    settingKey={TransactionSettingKey.LP}
  >
          <CreatePositionContextProvider initialState={initialState}>
            <PriceRangeContextProvider>
              <DepositContextProvider>
                <CreateTxContextProvider>
                  <Flex
    mt="$spacing24"
    width="100%"
    px="$spacing40"
    maxWidth={WIDTH.positionCard + WIDTH.sidebar + 80}
    $xl={{
      px: "$spacing12",
      maxWidth: WIDTH.positionCard,
      mx: "auto"
    }}
  >
                    <BreadcrumbNavContainer aria-label="breadcrumb-nav">
                      <BreadcrumbNavLink to="/liquidity">
                        {t("pool.positions.title")} <ChevronRight size={14} />
                      </BreadcrumbNavLink>
                      <BreadcrumbNavLink to="/positions/create">{t("pool.newPosition.title")}</BreadcrumbNavLink>
                    </BreadcrumbNavContainer>
                    <Flex
    row
    alignSelf="flex-end"
    alignItems="center"
    gap="$gap20"
    width="100%"
    justifyContent="space-between"
    mr="auto"
    mb="$spacing32"
    $md={{ flexDirection: "column", alignItems: "stretch" }}
  >
                      <Text variant="heading2">{t("position.new")}</Text>
                      <Toolbar defaultInitialToken={initialInputs[PositionField.TOKEN0]} />
                    </Flex>
                    <Flex row gap="$spacing20" justifyContent="space-between" width="100%">
                      {!media.xl && <Sidebar />}
                      <Flex gap="$spacing24" flex={1} maxWidth={WIDTH.positionCard} mb="$spacing28">
                        <CreatePositionInner />
                      </Flex>
                    </Flex>
                  </Flex>
                </CreateTxContextProvider>
              </DepositContextProvider>
            </PriceRangeContextProvider>
          </CreatePositionContextProvider>
        </TransactionSettingsContextProvider>
      </MultichainContextProvider>
    </Trace>;
}
